mapper.select:
SELECT *
FROM `order`
WHERE user_id = #{userId}
  AND activity_id = #{activityId}
  AND seckill_item_id = #{seckillItemId}
LIMIT 1

mapper.update:
UPDATE `order`
SET order_state = 6,
    cancel_reason = #{cancelReason},
    cancelled_at = #{cancelledAt}
WHERE id = #{id}
  AND order_state = 1
